import sqlite3, os
AREAS=['Uttara','Mirpur','Dhanmondi','Gulshan','Banani','Mohammadpur','Mohakhali','Farmgate','Badda','Rampura','Jatrabari','Old Dhaka']
COORDS={'Uttara':(23.8759,90.3795),'Mirpur':(23.8067,90.3686),'Dhanmondi':(23.7465,90.3760),'Gulshan':(23.7925,90.4078),'Banani':(23.7937,90.4065),'Mohammadpur':(23.7660,90.3584),'Mohakhali':(23.7808,90.4072),'Farmgate':(23.7587,90.3897),'Badda':(23.7806,90.4255),'Rampura':(23.7681,90.4228),'Jatrabari':(23.7104,90.4348),'Old Dhaka':(23.7100,90.4100)}
MEDS=[('Paracetamol','Paracetamol','Napa','500 mg','Tablet'),('Paracetamol','Paracetamol','Ace','500 mg','Tablet'),('Omeprazole','Omeprazole','Seclo','20 mg','Capsule'),('Esomeprazole','Esomeprazole','Nexum','20 mg','Tablet'),('Metformin','Metformin','Metfo','500 mg','Tablet'),('Amlodipine','Amlodipine','Amdocal','5 mg','Tablet'),('Losartan','Losartan','Losar','50 mg','Tablet'),('Atorvastatin','Atorvastatin','Atova','10 mg','Tablet'),('Cetirizine','Cetirizine','Cetriz','10 mg','Tablet'),('Fexofenadine','Fexofenadine','Fexo','120 mg','Tablet'),('Azithromycin','Azithromycin','Azithro','500 mg','Tablet'),('Amoxicillin','Amoxicillin','Moxacil','500 mg','Capsule'),('ORS','Oral Rehydration Salts','ORS','Standard','Sachet'),('Salbutamol','Salbutamol','Ventolin','100 mcg','Inhaler'),('Insulin Glargine','Insulin Glargine','Lantus','100 IU/ml','Injection')]
def seed(path):
 os.makedirs(os.path.dirname(path) or '.',exist_ok=True); c=sqlite3.connect(path); c.executescript('''DROP TABLE IF EXISTS hospitals; DROP TABLE IF EXISTS blood_inventory; DROP TABLE IF EXISTS pharmacies; DROP TABLE IF EXISTS medicine_inventory; DROP TABLE IF EXISTS donors; DROP TABLE IF EXISTS ambulances;
 CREATE TABLE hospitals(id INTEGER PRIMARY KEY,name TEXT,area TEXT,kind TEXT,phone TEXT,lat REAL,lng REAL,emergency INTEGER,icu INTEGER,beds INTEGER,services TEXT); CREATE TABLE blood_inventory(id INTEGER PRIMARY KEY,hospital_id INTEGER,blood_group TEXT,units INTEGER); CREATE TABLE pharmacies(id INTEGER PRIMARY KEY,name TEXT,area TEXT,address TEXT,phone TEXT,lat REAL,lng REAL); CREATE TABLE medicine_inventory(id INTEGER PRIMARY KEY,pharmacy_id INTEGER,medicine_name TEXT,generic_name TEXT,brand_name TEXT,strength TEXT,dosage_form TEXT,availability INTEGER,stock_quantity INTEGER); CREATE TABLE donors(id INTEGER PRIMARY KEY,name TEXT,area TEXT,blood_group TEXT,phone TEXT); CREATE TABLE ambulances(id INTEGER PRIMARY KEY,service_name TEXT,area TEXT,phone_number TEXT,alternate_phone TEXT,service_type TEXT,availability_status INTEGER,lat REAL,lng REAL,description TEXT);''')
 rows=[]
 for i,a in enumerate(AREAS,1):
  lat,lng=COORDS[a]; rows += [(i*2-1,f'{a} Community Hospital',a,'Government',f'02-900{i:03d}',lat,lng,1,1 if i%3 else 0,8+i%12,'Emergency, Trauma, Maternity'),(i*2,f'{a} Care Centre',a,'Private',f'02-800{i:03d}',lat+.004,lng+.005,1,1,5+i%10,'Emergency, ICU, Surgery')]
 rows[1]=(2,'Hospital B · Uttara Emergency Care Center','Uttara','Government','02-900002',23.8765,90.3805,1,1,18,'Emergency, ICU, Trauma, Blood Bank'); rows[2]=(3,'Hospital C · Uttara Relief Hospital','Uttara','Private','02-800002',23.881,90.384,1,1,14,'Emergency, ICU, Trauma, Blood Bank'); rows += [(25,'Dhaka Humanitarian Medical Centre','Farmgate','Government','02-900025',23.760,90.391,1,1,16,'Emergency, ICU, Trauma'),(26,'Buriganga Care Hospital','Old Dhaka','Private','02-800026',23.711,90.412,1,0,9,'Emergency, Surgery, Maternity')]
 c.executemany('INSERT INTO hospitals VALUES(?,?,?,?,?,?,?,?,?,?,?)',rows); c.executemany('INSERT INTO blood_inventory VALUES(?,?,?,?)',[(None,h,g,(h+j)%7+1) for h in range(1,27) for j,g in enumerate(['A+','A-','B+','B-','AB+','AB-','O+','O-'])])
 pharmacies=[]
 for i,a in enumerate(AREAS,1):
  lat,lng=COORDS[a]
  for j in range(2): pharmacies.append((None,f'{a} Health Pharmacy {j+1}',a,f'{a} main road',f'01700{i:03d}{j}',lat+.002*j,lng+.003*j))
 pharmacies += [(None,'Dhaka Community Pharmacy','Farmgate','Farmgate central','0170099911',23.760,90.391),(None,'South City Medicine Point','Old Dhaka','Old Dhaka central','0170099912',23.711,90.412)]
 c.executemany('INSERT INTO pharmacies VALUES(?,?,?,?,?,?,?)',pharmacies); c.executemany('INSERT INTO medicine_inventory VALUES(?,?,?,?,?,?,?,?,?)',[(None,pid,*m,1,(pid+k)%18+2) for pid in range(1,len(pharmacies)+1) for k,m in enumerate(MEDS[:5] if pid%3 else MEDS)])
 c.executemany('INSERT INTO donors VALUES(?,?,?,?,?)',[(None,f'Volunteer {i+1}',AREAS[i%12],['A+','B+','O+','AB+'][i%4],f'01800{i:05d}') for i in range(36)])
 ambulances=[]
 for i,a in enumerate(AREAS,1):
  lat,lng=COORDS[a]; ambulances += [(None,f'{a} Rapid Response',a,f'01900{i:04d}',f'01910{i:04d}','Basic life support',1 if i%4 else 0,lat,lng,'Demonstration ambulance contact'),(None,f'{a} Care Transit',a,f'01920{i:04d}',f'01930{i:04d}','Patient transport',1,lat+.003,lng+.002,'Demonstration ambulance contact')]
 c.executemany('INSERT INTO ambulances VALUES(?,?,?,?,?,?,?,?,?,?)',ambulances); c.commit(); c.close()
if __name__=='__main__': seed('database.db')
